llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Upadacitinib, a cyclopentyl-containing oral kinase inhibitor, was predicted to have high human oral bioavailability of 80%, supporting high F for a similar heteroaromatic kinase inhibitor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Brigatinib, a piperazine-aniline aminopyrimidine kinase inhibitor, showed absolute oral bioavailability of 57% in fasted healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Brigatinib absolute oral bioavailability was 77% in the fed state, further supporting high oral absorption for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib, an oral kinase inhibitor with a heteroaryl amine core, had an estimated absolute bioavailability of 75% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Imatinib, a piperazine-containing oral kinase inhibitor, has a mean absolute bioavailability of 98%, demonstrating that this scaffold class can achieve very high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Niraparib, an oral heteroaromatic drug, had an absolute bioavailability of 72.7% (90% CI 61.69–83.40), supporting high F for structurally related oral compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Trametinib, a complex oral kinase inhibitor, had a microtracer-determined absolute bioavailability of 72.3%, confirming high oral F in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam, a heteroaromatic oral drug with a piperazine moiety, has high oral bioavailability due to almost complete absorption and negligible first-pass extraction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple close structural analogs with piperazine-aniline and heteroaromatic kinase-inhibitor scaffolds show absolute oral bioavailability values of 57–98%, all clearly above the 20% threshold; the query molecule is therefore predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule itself.",
    "Some supporting records are predicted values or from different therapeutic classes, though the structural and mechanistic overlap is strong.",
    "Exact formulation and food-effect conditions for the query molecule are not specified in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

